const fail = (status, code, message) => [{ json: { error: { status, code, message } } }];

const { body = {}, headers = {} } = $input.first().json;
const accion = String(body.accion || '').trim();
const auth = headers.authorization || '';
const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
const PUBLICAS = ['crear', 'verificar', 'reenviar', 'recuperar', 'restablecer'];

if (![...PUBLICAS, 'perfil', 'actualizar', 'desactivar'].includes(accion)) {
  return fail(400, 'VALIDACION', 'Acción no válida');
}

if (PUBLICAS.includes(accion)) {
  const email = String(body.email || '').trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail(400, 'VALIDACION', 'El email no es válido');
  const password = String(body.password || '');
  const codigo = String(body.codigo || '').replace(/\s/g, '');
  if (accion === 'crear') {
    const nombre = String(body.nombre || '').trim();
    if (nombre.length < 2 || nombre.length > 80) return fail(400, 'VALIDACION', 'El nombre debe tener entre 2 y 80 caracteres');
    if (password.length < 8 || password.length > 128) return fail(400, 'VALIDACION', 'La contraseña debe tener entre 8 y 128 caracteres');
    return [{ json: { accion, nombre, email, password } }];
  }
  if (accion === 'verificar' || accion === 'restablecer') {
    if (!/^\d{6}$/.test(codigo)) return fail(400, 'VALIDACION', 'El código debe tener 6 dígitos');
  }
  if (accion === 'restablecer' && (password.length < 8 || password.length > 128)) {
    return fail(400, 'VALIDACION', 'La contraseña debe tener entre 8 y 128 caracteres');
  }
  return [{ json: { accion, email, codigo, password } }];
}

if (!token) return fail(401, 'SESION_INVALIDA', 'Sesión no válida');
return [{ json: { accion, token, nombre: body.nombre, password: body.password } }];

const fail = (status, code, message) => [{ json: { error: { status, code, message } } }];

const crypto = require('crypto');
const entrada = $('Validar entrada').first().json;

const previo = $input.all().map(i => i.json).find(r => r && r.usuario_id);
if (previo && previo.estado === 'PENDIENTE') {
  return fail(409, 'PENDIENTE_VERIFICACION', 'Ya hay un registro pendiente con ese email. Revisa tu correo o pide un código nuevo.');
}
if (previo) return fail(409, 'EMAIL_DUPLICADO', 'Ya existe una cuenta con ese email');

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.pbkdf2Sync(entrada.password, salt, 100000, 64, 'sha512').toString('hex');
const ahora = new Date();
const usuarioId = 'USR-' + crypto.randomUUID();

// Código de verificación: 6 dígitos, se guarda solo su hash y vence en 15 minutos
const codigo = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
const codigoId = 'COD-' + crypto.randomUUID();

return [{ json: {
  usuario: {
    usuario_id: usuarioId,
    nombre: entrada.nombre,
    email_normalizado: entrada.email,
    password_hash: hash,
    password_salt: salt,
    estado: 'PENDIENTE',
    fecha_registro: ahora.toISOString(),
    fecha_actualizacion: ahora.toISOString()
  },
  codigo: {
    codigo_id: codigoId, usuario_id: usuarioId, email_normalizado: entrada.email, tipo: 'VERIFICACION',
    codigo_hash: crypto.createHash('sha256').update(codigoId + ':' + codigo).digest('hex'),
    creado_en: ahora.toISOString(), expira_en: new Date(ahora.getTime() + 15 * 60 * 1000).toISOString(),
    estado: 'PENDIENTE', intentos: 0, usado_en: ''
  },
  notificacion: {
    usuario_id: usuarioId, tipo: 'VERIFICACION_EMAIL', titulo: 'Tu código de verificación',
    mensaje: 'Tu código para activar tu cuenta de EventPass es ' + codigo + '. Vence en 15 minutos. Si no creaste esta cuenta, ignora este mensaje.',
    mensaje_registro: 'Código de verificación enviado (no se guarda el código).',
    evento_id: '', inscripcion_id: '', clave_idempotencia: codigoId
  }
} }];

const fail = (status, code, message) => [{ json: { error: { status, code, message } } }];

const entrada = $('Validar entrada').first().json;
const fila = $input.all().map(i => i.json).find(r => r.session_token === entrada.token);

if (!fila || fila.estado !== 'ACTIVA') return fail(401, 'SESION_INVALIDA', 'Sesión no válida');
if (new Date(fila.expira_en) <= new Date()) return fail(401, 'SESION_INVALIDA', 'La sesión expiró');

return [{ json: { usuario_id: fila.usuario_id } }];

const fail = (status, code, message) => [{ json: { error: { status, code, message } } }];

const crypto = require('crypto');
const entrada = $('Validar entrada').first().json;
const usuarioId = $('Validar sesion').first().json.usuario_id;

const fila = $input.all().map(i => i.json).find(r => r.usuario_id === usuarioId);
if (!fila) return fail(404, 'NO_ENCONTRADO', 'Usuario no encontrado');
if (fila.estado !== 'ACTIVO') return fail(403, 'USUARIO_INACTIVO', 'La cuenta está inactiva');

const publico = (u) => ({
  usuario_id: u.usuario_id, nombre: u.nombre, email: u.email_normalizado,
  estado: u.estado, fecha_registro: u.fecha_registro
});

if (entrada.accion === 'perfil') {
  return [{ json: { accion: 'perfil', respuesta: publico(fila), message: 'Perfil obtenido' } }];
}

const ahora = new Date().toISOString();
const actualizado = {
  usuario_id: fila.usuario_id, nombre: fila.nombre, email_normalizado: fila.email_normalizado,
  password_hash: fila.password_hash, password_salt: fila.password_salt,
  estado: fila.estado, fecha_registro: fila.fecha_registro, fecha_actualizacion: ahora
};
let auditoria, message;

if (entrada.accion === 'desactivar') {
  actualizado.estado = 'INACTIVO';
  auditoria = { accion: 'DESACTIVAR', detalle: 'Cuenta desactivada por el usuario' };
  message = 'Cuenta desactivada';
} else {
  const nombre = entrada.nombre === undefined || entrada.nombre === null ? null : String(entrada.nombre).trim();
  const password = entrada.password ? String(entrada.password) : '';
  if (nombre === null && !password) return fail(400, 'VALIDACION', 'No hay nada que actualizar');
  if (nombre !== null && (nombre.length < 2 || nombre.length > 80)) return fail(400, 'VALIDACION', 'El nombre debe tener entre 2 y 80 caracteres');
  if (password && (password.length < 8 || password.length > 128)) return fail(400, 'VALIDACION', 'La contraseña debe tener entre 8 y 128 caracteres');

  const cambios = [];
  if (nombre !== null) { actualizado.nombre = nombre; cambios.push('nombre'); }
  if (password) {
    const salt = crypto.randomBytes(16).toString('hex');
    actualizado.password_salt = salt;
    actualizado.password_hash = crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
    cambios.push('password');
  }
  auditoria = { accion: 'ACTUALIZAR', detalle: 'Campos: ' + cambios.join(', ') };
  message = 'Perfil actualizado';
}

return [{ json: { accion: entrada.accion, update: actualizado, auditoria, respuesta: publico(actualizado), message } }];

const crypto = require('crypto');
const e = $('Validar entrada').first().json;
const usuario = $('Buscar cuenta').all().map(i => i.json).find(r => r && r.usuario_id && r.email_normalizado === e.email);
const codigos = $('Buscar codigos').all().map(i => i.json).filter(r => r && r.codigo_id && r.email_normalizado === e.email);

const MAX_INTENTOS = 5, VIGENCIA_MIN = 15, ESPERA_S = 60;
const ahora = new Date();
const iso = ahora.toISOString();
const tipo = ['verificar', 'reenviar'].includes(e.accion) ? 'VERIFICACION' : 'RECUPERACION';
const estadoRequerido = tipo === 'VERIFICACION' ? 'PENDIENTE' : 'ACTIVO';
const pendientes = codigos.filter(c => c.tipo === tipo && c.estado === 'PENDIENTE')
  .sort((a, b) => new Date(b.creado_en) - new Date(a.creado_en));

const plan = { status: 200, error: null, respuesta: {}, message: '', codigos_update: [], codigo_nuevo: null,
  usuario_update: null, cerrar_sesiones: false, usuario_id: usuario ? usuario.usuario_id : '', notificacion: null, auditoria: null };
const salir = () => [{ json: plan }];
const error = (status, code, message) => { plan.status = status; plan.error = { code, message }; return salir(); };
const fila = (c, cambios) => {
  const f = {};
  for (const k of ['codigo_id', 'usuario_id', 'email_normalizado', 'tipo', 'codigo_hash', 'creado_en', 'expira_en', 'estado', 'intentos', 'usado_en']) f[k] = c[k] ?? '';
  f.intentos = Number(f.intentos || 0);
  return Object.assign(f, cambios);
};
const cuenta = (cambios) => {
  const u = {};
  for (const k of ['usuario_id', 'nombre', 'email_normalizado', 'password_hash', 'password_salt', 'estado', 'fecha_registro', 'fecha_actualizacion']) u[k] = usuario[k] ?? '';
  return Object.assign(u, cambios, { fecha_actualizacion: iso });
};
const notif = (tipoNotif, titulo, mensaje, clave, registro) => ({
  usuario_id: usuario.usuario_id, tipo: tipoNotif, titulo, mensaje, mensaje_registro: registro || '',
  evento_id: '', inscripcion_id: '', clave_idempotencia: clave
});

// ---- pedir un código (reenviar verificación o recuperar contraseña) ----
if (e.accion === 'reenviar' || e.accion === 'recuperar') {
  // Mensaje genérico: no revela si el email existe ni en qué estado está la cuenta
  plan.message = 'Si el email está registrado, te enviamos un código. Revisa tu correo (y tu Telegram si lo vinculaste).';
  if (!usuario || usuario.estado !== estadoRequerido) return salir();

  const ultimo = codigos.filter(c => c.tipo === tipo).map(c => new Date(c.creado_en).getTime()).sort((a, b) => b - a)[0];
  const espera = ultimo ? Math.ceil((ultimo + ESPERA_S * 1000 - ahora.getTime()) / 1000) : 0;
  if (espera > 0) return error(429, 'ESPERA', 'Espera ' + espera + ' segundos antes de pedir otro código');

  for (const c of pendientes) plan.codigos_update.push(fila(c, { estado: 'CANCELADO' }));
  const codigo = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
  const codigoId = 'COD-' + crypto.randomUUID();
  plan.codigo_nuevo = {
    codigo_id: codigoId, usuario_id: usuario.usuario_id, email_normalizado: usuario.email_normalizado, tipo,
    codigo_hash: crypto.createHash('sha256').update(codigoId + ':' + codigo).digest('hex'),
    creado_en: iso, expira_en: new Date(ahora.getTime() + VIGENCIA_MIN * 60 * 1000).toISOString(),
    estado: 'PENDIENTE', intentos: 0, usado_en: ''
  };
  plan.notificacion = tipo === 'VERIFICACION'
    ? notif('VERIFICACION_EMAIL', 'Tu código de verificación',
        'Tu código para activar tu cuenta de EventPass es ' + codigo + '. Vence en ' + VIGENCIA_MIN + ' minutos. Si no creaste esta cuenta, ignora este mensaje.',
        codigoId, 'Código de verificación reenviado (no se guarda el código).')
    : notif('RECUPERACION_CUENTA', 'Código para recuperar tu cuenta',
        'Tu código para cambiar la contraseña de EventPass es ' + codigo + '. Vence en ' + VIGENCIA_MIN + ' minutos. Si no lo pediste, ignora este mensaje: tu contraseña sigue igual.',
        codigoId, 'Código de recuperación enviado (no se guarda el código).');
  plan.auditoria = { accion: tipo === 'VERIFICACION' ? 'REENVIAR_CODIGO' : 'SOLICITAR_RECUPERACION', detalle: 'Código ' + codigoId + ' enviado' };
  return salir();
}

// ---- usar un código (verificar cuenta o restablecer contraseña) ----
const INVALIDO = 'El código no es válido o ya venció. Pide uno nuevo.';
if (!usuario) return error(400, 'CODIGO_INVALIDO', INVALIDO);
if (tipo === 'VERIFICACION' && usuario.estado === 'ACTIVO') return error(409, 'YA_VERIFICADA', 'Tu cuenta ya está verificada. Inicia sesión.');
if (usuario.estado !== estadoRequerido) return error(400, 'CODIGO_INVALIDO', INVALIDO);

const actual = pendientes[0];
if (!actual) return error(400, 'CODIGO_INVALIDO', INVALIDO);
if (new Date(actual.expira_en) <= ahora) {
  plan.codigos_update.push(fila(actual, { estado: 'EXPIRADO' }));
  return error(400, 'CODIGO_VENCIDO', 'El código venció. Pide uno nuevo.');
}

const calculado = crypto.createHash('sha256').update(actual.codigo_id + ':' + e.codigo).digest('hex');
const guardado = String(actual.codigo_hash);
const coincide = calculado.length === guardado.length && crypto.timingSafeEqual(Buffer.from(calculado), Buffer.from(guardado));
if (!coincide) {
  const intentos = Number(actual.intentos || 0) + 1;
  const agotado = intentos >= MAX_INTENTOS;
  plan.codigos_update.push(fila(actual, { intentos, estado: agotado ? 'CANCELADO' : 'PENDIENTE' }));
  plan.auditoria = { accion: tipo === 'VERIFICACION' ? 'VERIFICAR_EMAIL' : 'RESTABLECER_PASSWORD', resultado: 'ERROR', detalle: 'Código incorrecto (intento ' + intentos + ')' };
  return error(400, 'CODIGO_INVALIDO', agotado
    ? 'Demasiados intentos fallidos. Pide un código nuevo.'
    : 'Código incorrecto. Te quedan ' + (MAX_INTENTOS - intentos) + ' intentos.');
}

plan.codigos_update.push(fila(actual, { estado: 'USADO', usado_en: iso }));
if (tipo === 'VERIFICACION') {
  plan.usuario_update = cuenta({ estado: 'ACTIVO' });
  plan.notificacion = notif('BIENVENIDA', '¡Bienvenid@ a EventPass!',
    'Tu cuenta quedó verificada. Ya puedes iniciar sesión, vincular tu Telegram desde tu perfil e inscribirte a los eventos de Halloween.',
    'BIENVENIDA|' + usuario.usuario_id);
  plan.auditoria = { accion: 'VERIFICAR_EMAIL', detalle: 'Email verificado con el código ' + actual.codigo_id };
  plan.respuesta = { usuario_id: usuario.usuario_id, nombre: usuario.nombre, email: usuario.email_normalizado, estado: 'ACTIVO' };
  plan.message = 'Cuenta verificada. Ya puedes iniciar sesión.';
} else {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.pbkdf2Sync(e.password, salt, 100000, 64, 'sha512').toString('hex');
  plan.usuario_update = cuenta({ password_hash: hash, password_salt: salt });
  plan.cerrar_sesiones = true;
  plan.notificacion = notif('PASSWORD_CAMBIADA', 'Tu contraseña fue cambiada',
    'La contraseña de tu cuenta de EventPass se cambió con un código de recuperación y se cerraron tus sesiones abiertas. Si no fuiste tú, recupera tu cuenta de inmediato.',
    'PASSWORD|' + actual.codigo_id);
  plan.auditoria = { accion: 'RESTABLECER_PASSWORD', detalle: 'Contraseña restablecida con el código ' + actual.codigo_id };
  plan.message = 'Contraseña actualizada. Inicia sesión con tu nueva contraseña.';
}
return salir();

return [{ json: { filas: $input.all().map(i => i.json)
  .filter(s => s && s.session_id && s.estado === 'ACTIVA' && s.usuario_id === $('Evaluar codigo').first().json.usuario_id)
  .map(s => ({ session_id: s.session_id, usuario_id: s.usuario_id, session_token: s.session_token, creada_en: s.creada_en,
    expira_en: s.expira_en, estado: 'CERRADA', cerrada_en: new Date().toISOString(), ultima_validacion: s.ultima_validacion })) } }];
